WITH paid AS (SELECT o.order_id,o.customer_id FROM orders o WHERE o.status = 'paid' AND o.ordered_at >= TIMESTAMPTZ '2024-01-01 00:00:00+00' AND o.ordered_at < TIMESTAMPTZ '2025-01-01 00:00:00+00'),counts AS (SELECT customer_id,count(*) AS paid_order_count FROM paid GROUP BY customer_id),revenue AS (SELECT p.customer_id,sum(i.qty::DECIMAL(18,0)*i.unit_price)::DECIMAL(38,2) AS gross_revenue FROM paid p JOIN order_items i USING(order_id) GROUP BY p.customer_id),refunds AS (SELECT p.customer_id,sum(r.refund_amount)::DECIMAL(38,2) AS refund_amount FROM paid p JOIN order_items i USING(order_id) JOIN returns r USING(order_item_id) WHERE r.status='refunded' GROUP BY p.customer_id) SELECT c.customer_id,coalesce(n.paid_order_count,0)::BIGINT AS paid_order_count,coalesce(v.gross_revenue,0)::DECIMAL(38,2) AS gross_revenue,coalesce(r.refund_amount,0)::DECIMAL(38,2) AS refund_amount,CASE WHEN coalesce(n.paid_order_count,0)>0 THEN 'paid' ELSE 'no_paid' END AS cohort FROM customers c JOIN counts n USING(customer_id) LEFT JOIN revenue v USING(customer_id) LEFT JOIN refunds r USING(customer_id) ORDER BY c.customer_id;
